<style>
*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#eef2ff;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.wrap{max-width:1450px;margin:auto;padding:32px}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:10px;padding:11px 16px;background:#1e293b;color:#fff;cursor:pointer;font-weight:700;text-decoration:none}.btn.primary{background:#2563eb}.btn.danger{background:#7f1d1d}.card{background:#111827;border:1px solid #1f2937;border-radius:18px;padding:0;box-shadow:0 18px 50px #0003;overflow:hidden}.card-header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:22px;border-bottom:1px solid #1f2937}.card-title{font-size:20px;font-weight:850;margin:0}.card-header-actions{display:flex;gap:10px;align-items:center}.card-body{padding:22px}.project-list-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 14px}.project-list-head h2{font-size:18px;margin:0}.project-count{font-size:12px;font-weight:800;color:#93c5fd;background:#172554;border:1px solid #2b4b83;border-radius:999px;padding:6px 11px;white-space:nowrap}.tabs{display:flex;gap:8px;margin-bottom:18px;flex-wrap:wrap}.tab{display:inline-flex;align-items:center;gap:7px;padding:9px 14px;border:1px solid #263246;border-radius:10px;background:#0d1424;color:#94a3b8;text-decoration:none;font-size:12px;font-weight:800}.tab:hover{border-color:#3b82f6;color:#dbeafe}.tab.active{background:#2563eb;border-color:#2563eb;color:#fff}.tab-count{font-size:10px;opacity:.8}.project-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.project{position:relative;border:1px solid #263246;background:#0d1424;border-radius:14px;padding:17px;margin:0;cursor:grab;transition:.18s}.project:active{cursor:grabbing}.project.dragging{opacity:.45;transform:scale(.99)}.project.drag-over{border-color:#38bdf8;box-shadow:0 0 0 2px #38bdf822}.project-number{position:absolute;left:16px;top:17px;width:30px;height:30px;border-radius:9px;background:#172554;color:#93c5fd;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:900}.project-head{display:flex;justify-content:space-between;gap:12px}.project-name{font-weight:800;font-size:16px}.meta{font-size:12px;color:#94a3b8;margin-top:5px}.status-badge{display:inline-flex;align-items:center;margin-top:8px;padding:4px 8px;border-radius:999px;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.06em}.status-badge.ongoing{background:#052e2b;color:#6ee7b7;border:1px solid #065f46}.status-badge.completed{background:#172033;color:#94a3b8;border:1px solid #334155}.progress-summary{margin-top:14px}.progress-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.progress-label{font-size:11px;color:#64748b;text-transform:uppercase;letter-spacing:.08em;font-weight:800}.progress-value{font-size:16px;font-weight:850;color:#7dd3fc}.progress-bar{height:7px;border-radius:99px;background:#1e293b;overflow:hidden}.progress-fill{height:100%;border-radius:99px;background:#38bdf8}.project-actions{display:flex;justify-content:flex-end;align-items:center;gap:8px;margin-top:13px}.project-actions form{margin:0}.action-icon{width:40px;height:40px;padding:0;border-radius:10px;font-size:18px;line-height:1}.action-icon svg{width:18px;height:18px;display:block}.drag-handle{float:right;color:#64748b;font-size:18px;line-height:1;margin-left:8px;user-select:none}.empty{padding:40px;text-align:center;color:#64748b}.order-status{font-size:11px;color:#64748b;margin:-8px 0 14px}.modal-backdrop{position:fixed;inset:0;background:#020617b8;backdrop-filter:blur(7px);display:none;align-items:center;justify-content:center;padding:20px;z-index:1000}.modal-backdrop.open{display:flex}.progress-modal{width:min(520px,100%);background:linear-gradient(145deg,#121a2b,#0d1423);border:1px solid #2b3a52;border-radius:22px;box-shadow:0 30px 90px #0008;padding:26px}.modal-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:24px}.modal-eyebrow{font-size:11px;color:#7dd3fc;font-weight:850;text-transform:uppercase;letter-spacing:.1em}.modal-title{font-size:22px;font-weight:850;margin-top:5px}.modal-client{font-size:12px;color:#64748b;margin-top:4px}.modal-close{width:38px;height:38px;border:1px solid #2b3a52;border-radius:10px;background:#172033;color:#cbd5e1;font-size:20px;cursor:pointer}.modal-close:hover{background:#1e293b;color:#fff}.modal-progress-box{background:#0a1120;border:1px solid #2b3a52;border-radius:16px;padding:20px}.modal-progress-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.modal-progress-label{font-size:12px;color:#cbd5e1;font-weight:850;text-transform:uppercase;letter-spacing:.08em}.modal-progress-value{font-size:30px;font-weight:900;color:#7dd3fc}.modal-slider{width:100%;height:10px;appearance:none;-webkit-appearance:none;border-radius:99px;background:linear-gradient(to right,#38bdf8 0%,#38bdf8 var(--progress),#1e293b var(--progress),#1e293b 100%);outline:none;cursor:pointer}.modal-slider::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:23px;height:23px;border-radius:50%;background:#fff;border:3px solid #38bdf8;box-shadow:0 3px 14px #0006}.modal-slider::-moz-range-thumb{width:17px;height:17px;border-radius:50%;background:#fff;border:3px solid #38bdf8}.modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.saving{opacity:.7;pointer-events:none}@media(max-width:760px){.project-grid{grid-template-columns:1fr}.wrap{padding:18px}.project-actions{justify-content:flex-end}.modal-actions{flex-direction:column}.modal-actions .btn{width:100%}.card-header{align-items:flex-start;flex-direction:column}.card-header-actions{width:100%;flex-wrap:wrap}.card-header-actions .btn{flex:1}}
</style>
</head>
<body>
@php
    $tab = request('tab', 'ongoing');
    if (!in_array($tab, ['ongoing', 'completed', 'all'], true)) $tab = 'ongoing';
    $ongoingProjects = $projects->where('display_status', 'visible');
    $completedProjects = $projects->where('display_status', 'hidden');
    $visibleProjects = $tab === 'completed' ? $completedProjects : ($tab === 'all' ? $projects : $ongoingProjects);
@endphp
<div class="wrap">
<x-admin-header />
<div class="card"><div class="card-header"><h1 class="card-title">Project Management</h1><div class="card-header-actions"><a class="btn primary" href="{{ route('admin.projects.create') }}">+ Tambah Project</a><a class="btn" href="{{ route('monitor') }}" target="_blank">Buka Monitor ↗</a></div></div><div class="card-body">
<div class="project-list-head"><h2>{{ $tab === 'completed' ? 'Completed Projects' : ($tab === 'all' ? 'All Projects' : 'Ongoing Projects') }}</h2><span class="project-count">{{ $visibleProjects->count() }} Project</span></div>
<div class="tabs">
<a class="tab {{ $tab === 'ongoing' ? 'active' : '' }}" href="{{ route('admin.projects.index', ['tab'=>'ongoing']) }}">Ongoing <span class="tab-count">{{ $ongoingProjects->count() }}</span></a>
<a class="tab {{ $tab === 'completed' ? 'active' : '' }}" href="{{ route('admin.projects.index', ['tab'=>'completed']) }}">Completed <span class="tab-count">{{ $completedProjects->count() }}</span></a>
<a class="tab {{ $tab === 'all' ? 'active' : '' }}" href="{{ route('admin.projects.index', ['tab'=>'all']) }}">All <span class="tab-count">{{ $projects->count() }}</span></a>
</div>
<div class="order-status" id="orderStatus">↕ Drag project untuk mengatur urutan tampil di monitor. Klik progress untuk mengubah progress.</div>
<div id="projectList" class="project-grid">
@forelse($visibleProjects as $project)
<div class="project" draggable="true" data-id="{{ $project->id }}">
<span class="project-number">{{ $loop->iteration }}</span><span class="drag-handle">⋮⋮</span>
<div class="project-head"><div><div class="project-name">{{ $project->name }}</div><div class="meta">{{ $project->client }} · {{ str_replace('_',' ',ucfirst($project->project_type)) }}</div><span class="status-badge {{ $project->display_status === 'hidden' ? 'completed' : 'ongoing' }}">{{ $project->display_status === 'hidden' ? 'Completed' : 'Ongoing' }}</span></div></div>
<div class="progress-summary"><div class="progress-head"><span class="progress-label">Progress</span><button type="button" class="progress-value progress-trigger" style="border:0;background:none;padding:0;cursor:pointer" data-id="{{ $project->id }}" data-name="{{ e($project->name) }}" data-client="{{ e($project->client) }}" data-progress="{{ $project->progress }}">{{ $project->progress }}%</button></div><div class="progress-bar"><div class="progress-fill" style="width:{{ $project->progress }}%"></div></div></div>
<div class="meta">Target: {{ $project->target_completion_date?->format('d M Y') ?? '-' }} · Month: {{ $project->project_month?->format('M Y') ?? '-' }}</div>@if($project->location)<div class="meta">📍 {{ $project->location }}</div>@endif
<div class="project-actions"><a class="btn action-icon" href="{{ route('admin.projects.show',$project) }}" title="Detail" aria-label="Detail"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/></svg></a><a class="btn primary action-icon" href="{{ route('admin.projects.edit',$project) }}" title="Edit" aria-label="Edit"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l1-4Z"/></svg></a><form method="POST" action="{{ route('admin.projects.destroy',$project) }}" class="delete-form">@csrf @method('DELETE')<button class="btn danger action-icon" type="submit" title="Hapus" aria-label="Hapus"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 15H6L5 6"/><path d="M10 11v6M14 11v6"/></svg></button></form></div>
</div>
@empty<div class="empty">Belum ada project di tab ini.</div>@endforelse
</div></div></div>
<div class="modal-backdrop" id="progressModal" aria-hidden="true"><div class="progress-modal" role="dialog" aria-modal="true" aria-labelledby="progressModalTitle"><div class="modal-head"><div><div class="modal-eyebrow">Update Progress</div><div class="modal-title" id="progressModalTitle">Project</div><div class="modal-client" id="progressModalClient">Client</div></div><button type="button" class="modal-close" id="progressClose" aria-label="Tutup">×</button></div><div class="modal-progress-box"><div class="modal-progress-head"><span class="modal-progress-label">Project Progress</span><span class="modal-progress-value" id="modalProgressValue">0%</span></div><input class="modal-slider" id="modalProgressSlider" type="range" min="0" max="100" step="1" value="0" style="--progress:0%"></div><div class="modal-actions"><button type="button" class="btn" id="progressCancel">Batal</button><button type="button" class="btn primary" id="progressSave">Simpan Progress →</button></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
<script>
const csrf='{{ csrf_token() }}';document.querySelectorAll('.delete-form').forEach(form=>form.addEventListener('submit',function(e){e.preventDefault();Swal.fire({title:'Hapus project?',text:'Project ini akan dihapus permanen.',icon:'warning',showCancelButton:true,confirmButtonText:'Ya, hapus',cancelButtonText:'Batal',confirmButtonColor:'#dc2626'}).then(r=>{if(r.isConfirmed)this.submit()})}));
@if(session('success'))Swal.fire({toast:true,position:'top-end',icon:'success',title:@json(session('success')),showConfirmButton:false,timer:2200,timerProgressBar:true});@endif
const modal=document.getElementById('progressModal'),slider=document.getElementById('modalProgressSlider'),value=document.getElementById('modalProgressValue'),title=document.getElementById('progressModalTitle'),client=document.getElementById('progressModalClient');let activeId=null;function syncProgress(){value.textContent=slider.value+'%';slider.style.setProperty('--progress',slider.value+'%')}function openProgress(trigger){activeId=trigger.dataset.id;title.textContent=trigger.dataset.name;client.textContent=trigger.dataset.client;slider.value=trigger.dataset.progress;syncProgress();modal.classList.add('open');modal.setAttribute('aria-hidden','false');setTimeout(()=>slider.focus(),50)}function closeProgress(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');activeId=null}document.querySelectorAll('.progress-trigger').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();openProgress(el)}));slider.addEventListener('input',syncProgress);document.getElementById('progressClose').addEventListener('click',closeProgress);document.getElementById('progressCancel').addEventListener('click',closeProgress);modal.addEventListener('click',e=>{if(e.target===modal)closeProgress()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))closeProgress()});
document.getElementById('progressSave').addEventListener('click',async()=>{if(!activeId)return;const button=document.getElementById('progressSave');button.classList.add('saving');button.textContent='Menyimpan...';try{const response=await fetch(`{{ url('/admin/projects') }}/${activeId}/progress`,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({progress:Number(slider.value)})});const data=await response.json();if(!response.ok||!data.success)throw new Error('Gagal menyimpan');closeProgress();Swal.fire({toast:true,position:'top-end',icon:'success',title:'Progress diperbarui',showConfirmButton:false,timer:1500});setTimeout(()=>location.reload(),350)}catch(error){Swal.fire({icon:'error',title:'Gagal menyimpan',text:'Progress belum berhasil diperbarui.'})}finally{button.classList.remove('saving');button.textContent='Simpan Progress →'}});
const list=document.getElementById('projectList');let dragged=null;document.querySelectorAll('.project').forEach(card=>{card.addEventListener('dragstart',()=>{dragged=card;card.classList.add('dragging')});card.addEventListener('dragend',()=>{card.classList.remove('dragging');document.querySelectorAll('.project').forEach(x=>x.classList.remove('drag-over'));saveOrder()});card.addEventListener('dragover',e=>{e.preventDefault();if(dragged&&dragged!==card)card.classList.add('drag-over')});card.addEventListener('dragleave',()=>card.classList.remove('drag-over'));card.addEventListener('drop',e=>{e.preventDefault();card.classList.remove('drag-over');if(!dragged||dragged===card)return;const rect=card.getBoundingClientRect();const after=e.clientY>rect.top+rect.height/2;list.insertBefore(dragged,after?card.nextSibling:card)})});async function saveOrder(){const ids=[...list.querySelectorAll('.project')].map(x=>x.dataset.id);if(!ids.length)return;try{await fetch('{{ route('admin.projects.reorder') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({ids})})}catch(e){console.error(e)}}
</script>
</body>
</html>
